1	/** Pure replay fold and strict decoders for durable completion-standard changes. */
2	
3	import type { SessionEvent } from '@deepseek-ai/dsh-session'
4	import { GoalId } from '@deepseek-ai/dsh-goal'
5	import { CheckId, isKebabCase, StandardId, VERIFICATION_CHANGE_VERSION } from './runtime.ts'
6	import type {
7	  CertificateIsolation,
8	  CheckResult,
9	  CheckStatus,
10	  CompletionStandardSnapshot,
11	  RelaxedCheck,
12	  RunExecutor,
13	  StandardCheck,
14	  StandardRef,
15	  VerificationCertificate,
16	} from './types.ts'
17	import type {
18	  CertificateChangeMeta,
19	  DirectiveChangeMeta,
20	  FoldedVerification,
21	  RelaxationChangeMeta,
22	  StandardChangeMeta,
23	  StandardOperation,
24	  VerificationRunChangeMeta,
25	} from './domain.ts'
26	
27	const OPERATIONS: ReadonlySet<StandardOperation> = new Set(['author', 'extend'])
28	const ISOLATIONS: ReadonlySet<CertificateIsolation> = new Set(['none', 'process', 'host'])
29	const EXECUTORS: ReadonlySet<RunExecutor> = new Set(['runner', 'agent-reported'])
30	const CERTIFIED_STATUSES: ReadonlySet<CheckStatus> = new Set(['pass'])
31	const RUN_STATUSES: ReadonlySet<CheckStatus> = new Set(['pass', 'fail'])
32	const RUN_KEYS = ['attempt', 'executor', 'isolation', 'kind', 'recordedAt', 'results', 'standard', 'version']
33	const HEX_DIGEST = /^[0-9a-f]+$/
34	
35	/** Mutable accumulator kept private to the pure fold. */
36	export interface VerificationFoldState {
37	  standard: CompletionStandardSnapshot | undefined
38	  certificate: VerificationCertificate | undefined
39	  directivesIssued: number
40	  runsRecorded: number
41	  lastRun: VerificationRunChangeMeta | undefined
42	  createdAt: number | undefined
43	  updatedAt: number | undefined
44	  lastRef: StandardRef | undefined
45	  seenStandardIds: Set<CompletionStandardSnapshot['id']>
46	}
47	
48	/**
49	 * Attempt number the next run of one standard must carry. Authorship never
50	 * reuses a standard id, so the runs of one standard are contiguous in the log
51	 * and the last one carries their count.
52	 * @param state - fold accumulator covering every prior event.
53	 * @param id - standard the next run covers.
54	 * @returns one plus the runs already recorded for that standard id.
55	 */
56	export function nextRunAttempt(state: VerificationFoldState, id: CompletionStandardSnapshot['id']): number {
57	  const last = state.lastRun
58	  return (last !== undefined && last.standard.id === id ? last.attempt : 0) + 1
59	}
60	
61	/**
62	 * Build an empty replay accumulator.
63	 * @returns mutable state with no current standard or prior ref.
64	 */
65	export function emptyVerificationFoldState(): VerificationFoldState {
66	  return {
67	    standard: undefined,
68	    certificate: undefined,
69	    directivesIssued: 0,
70	    runsRecorded: 0,
71	    lastRun: undefined,
72	    createdAt: undefined,
73	    updatedAt: undefined,
74	    lastRef: undefined,
75	    seenStandardIds: new Set(),
76	  }
77	}
78	
79	// Strict per-domain decoders keep their own guards (the goal fold is the template).
80	/* jscpd:ignore-start */
81	/** Whether a value is a JSON record rather than an array. */
82	function isRecord(value: unknown): value is Record<string, unknown> {
83	  return typeof value === 'object' && value !== null && !Array.isArray(value)
84	}
85	
86	/** Require one positive safe integer. */
87	function positiveInteger(value: unknown, field: string): number {
88	  if (typeof value !== 'number' || !Number.isSafeInteger(value) || value < 1) {
89	    throw new Error(`verification change ${field} must be a positive safe integer`)
90	  }
91	  return value
92	}
93	
94	/** Require one non-negative safe integer. */
95	function nonNegativeInteger(value: unknown, field: string): number {
96	  if (typeof value !== 'number' || !Number.isSafeInteger(value) || value < 0) {
97	    throw new Error(`verification change ${field} must be a non-negative safe integer`)
98	  }
99	  return value
100	}
101	/* jscpd:ignore-end */
102	
103	/** Require one lowercase hex digest. */
104	function hexDigest(value: unknown, field: string): string {
105	  if (typeof value !== 'string' || !HEX_DIGEST.test(value)) {
106	    throw new Error(`verification change ${field} must be a lowercase hex digest`)
107	  }
108	  return value
109	}
110	
111	/** Require one non-empty trim-normalized string. */
112	function normalizedText(value: unknown, field: string): string {
113	  if (typeof value !== 'string' || value.trim().length === 0 || value !== value.trim()) {
114	    throw new Error(`verification change ${field} must be non-empty and normalized`)
115	  }
116	  return value
117	}
118	
119	/** Require an exact sorted key set. */
120	function requireKeys(value: Record<string, unknown>, expected: readonly string[], subject: string): void {
121	  const keys = Object.keys(value).sort().join(',')
122	  const wanted = [...expected].sort().join(',')
123	  if (keys !== wanted) {
124	    throw new Error(`verification change ${subject} must have exactly ${wanted} fields`)
125	  }
126	}
127	
128	/** Decode and validate one check. */
129	function decodeCheck(value: unknown, subject: string): StandardCheck {
130	  if (!isRecord(value)) throw new Error(`verification change ${subject} must be a record`)
131	  requireKeys(value, ['id', 'outcome', 'run'], subject)
132	  const rawId = value['id']
133	  if (typeof rawId !== 'string' || !isKebabCase(rawId)) {
134	    throw new Error(`verification change ${subject}.id must be lower-kebab-case`)
135	  }
136	  return {
137	    id: CheckId(rawId),
138	    outcome: normalizedText(value['outcome'], `${subject}.outcome`),
139	    run: normalizedText(value['run'], `${subject}.run`),
140	  }
141	}
142	
143	/** Decode and validate one relaxed entry. */
144	function decodeRelaxed(value: unknown, subject: string): RelaxedCheck {
145	  if (!isRecord(value)) throw new Error(`verification change ${subject} must be a record`)
146	  requireKeys(value, ['check', 'evidence'], subject)
147	  return {
148	    check: decodeCheck(value['check'], `${subject}.check`),
149	    evidence: normalizedText(value['evidence'], `${subject}.evidence`),
150	  }
151	}
152	
153	/** Decode and validate one full standard snapshot. */
154	function decodeSnapshot(value: unknown): CompletionStandardSnapshot {
155	  if (!isRecord(value)) throw new Error('verification change standard must be a record')
156	  requireKeys(value, ['checks', 'goalId', 'id', 'relaxed', 'revision'], 'standard')
157	  if (typeof value['id'] !== 'string' || value['id'].length === 0) {
158	    throw new Error('verification change standard.id must be a non-empty string')
159	  }
160	  if (typeof value['goalId'] !== 'string' || value['goalId'].length === 0) {
161	    throw new Error('verification change standard.goalId must be a non-empty string')
162	  }
163	  if (!Array.isArray(value['checks'])) throw new Error('verification change standard.checks must be an array')
164	  if (!Array.isArray(value['relaxed'])) throw new Error('verification change standard.relaxed must be an array')
165	  const checks = value['checks'].map((check, index) => decodeCheck(check, `standard.checks[${index}]`))
166	  const relaxed = value['relaxed'].map((entry, index) => decodeRelaxed(entry, `standard.relaxed[${index}]`))
167	  const ids = new Set<string>()
168	  for (const check of checks) {
169	    if (ids.has(check.id)) throw new Error(`verification change standard.checks repeats id "${check.id}"`)
170	    ids.add(check.id)
171	  }
172	  for (const entry of relaxed) {
173	    if (ids.has(entry.check.id)) {
174	      throw new Error(`verification change standard.relaxed repeats id "${entry.check.id}"`)
175	    }
176	    ids.add(entry.check.id)
177	  }
178	  return {
179	    id: StandardId(value['id']),
180	    revision: positiveInteger(value['revision'], 'standard.revision'),
181	    goalId: GoalId(value['goalId']),
182	    checks,
183	    relaxed,
184	  }
185	}
186	
187	/** Decode and validate one standard ref. */
188	function decodeRef(value: unknown, subject: string): StandardRef {
189	  if (!isRecord(value)) throw new Error(`verification change ${subject} must be a record`)
190	  requireKeys(value, ['id', 'revision'], subject)
191	  if (typeof value['id'] !== 'string' || value['id'].length === 0) {
192	    throw new Error(`verification change ${subject}.id must be a non-empty string`)
193	  }
194	  return { id: StandardId(value['id']), revision: positiveInteger(value['revision'], `${subject}.revision`) }
195	}
196	
197	/** Decode one check result, admitting exactly the statuses its carrier allows. */
198	function decodeResult(
199	  value: unknown,
200	  subject: string,
201	  admitted: ReadonlySet<CheckStatus>,
202	  requirement: string,
203	): CheckResult {
204	  if (!isRecord(value)) throw new Error(`verification change ${subject} must be a record`)
205	  requireKeys(value, ['checkId', 'evidence', 'status'], subject)
206	  const rawCheckId = value['checkId']
207	  if (typeof rawCheckId !== 'string' || !isKebabCase(rawCheckId)) {
208	    throw new Error(`verification change ${subject}.checkId must be lower-kebab-case`)
209	  }
210	  const status = value['status'] as CheckStatus
211	  if (!admitted.has(status)) {
212	    throw new Error(`verification change ${subject}.status must be ${requirement}`)
213	  }
214	  return {
215	    checkId: CheckId(rawCheckId),
216	    status,
217	    evidence: normalizedText(value['evidence'], `${subject}.evidence`),
218	  }
219	}
220	
221	/** Decode one passing certificate result. */
222	function decodeCertificateResult(value: unknown, subject: string): CheckResult {
223	  return decodeResult(value, subject, CERTIFIED_STATUSES, '"pass" inside a certificate')
224	}
225	
226	/** Decode one recorded run result, passing or failing. */
227	function decodeRunResult(value: unknown, subject: string): CheckResult {
228	  return decodeResult(value, subject, RUN_STATUSES, '"pass" or "fail"')
229	}
230	
231	/** Shared timestamp validation for standard-shaped changes. */
232	function decodeTimestamps(value: Record<string, unknown>): { createdAt: number; updatedAt: number } {
233	  const createdAt = nonNegativeInteger(value['createdAt'], 'createdAt')
234	  const updatedAt = nonNegativeInteger(value['updatedAt'], 'updatedAt')
235	  if (updatedAt < createdAt) throw new Error('verification change updatedAt cannot precede createdAt')
236	  return { createdAt, updatedAt }
237	}
238	
239	/** Require a self-declared payload version. */
240	function requireVersion(value: Record<string, unknown>): void {
241	  if (value['version'] !== VERIFICATION_CHANGE_VERSION) {
242	    throw new Error(`unsupported verification change version ${String(value['version'])}`)
243	  }
244	}
245	
246	/**
247	 * Decode a value that declares itself as a standard change. Unrelated values
248	 * return `undefined`; malformed standard changes fail replay loudly.
249	 * @param value - candidate durable payload.
250	 * @returns validated standard change or `undefined` for another value kind.
251	 */
252	export function decodeStandardChange(value: unknown): StandardChangeMeta | undefined {
253	  if (!isRecord(value) || value['kind'] !== 'verification/standard') return undefined
254	  requireVersion(value)
255	  requireKeys(value, ['createdAt', 'kind', 'operation', 'standard', 'updatedAt', 'version'], 'standard change')
256	  if (typeof value['operation'] !== 'string' || !OPERATIONS.has(value['operation'] as StandardOperation)) {
257	    throw new Error('verification change operation is invalid')
258	  }
259	  return {
260	    kind: 'verification/standard',
261	    version: VERIFICATION_CHANGE_VERSION,
262	    operation: value['operation'] as StandardOperation,
263	    standard: decodeSnapshot(value['standard']),
264	    ...decodeTimestamps(value),
265	  }
266	}
267	
268	/**
269	 * Decode a value that declares itself as a relaxation. Unrelated values
270	 * return `undefined`; malformed relaxations fail replay loudly.
271	 * @param value - candidate durable payload.
272	 * @returns validated relaxation or `undefined` for another value kind.
273	 */
274	export function decodeRelaxationChange(value: unknown): RelaxationChangeMeta | undefined {
275	  if (!isRecord(value) || value['kind'] !== 'verification/relaxation') return undefined
276	  requireVersion(value)
277	  requireKeys(value, ['checkId', 'createdAt', 'kind', 'standard', 'updatedAt', 'version'], 'relaxation')
278	  const rawCheckId = value['checkId']
279	  if (typeof rawCheckId !== 'string' || !isKebabCase(rawCheckId)) {
280	    throw new Error('verification change relaxation checkId must be lower-kebab-case')
281	  }
282	  const standard = decodeSnapshot(value['standard'])
283	  const last = standard.relaxed[standard.relaxed.length - 1]
284	  if (last === undefined || last.check.id !== rawCheckId) {
285	    throw new Error('verification change relaxation must end the snapshot relaxed list with its check')
286	  }
287	  return {
288	    kind: 'verification/relaxation',
289	    version: VERIFICATION_CHANGE_VERSION,
290	    checkId: CheckId(rawCheckId),
291	    standard,
292	    ...decodeTimestamps(value),
293	  }
294	}
295	
296	/**
297	 * Decode a value that declares itself as a run. Unrelated values return
298	 * `undefined`; malformed runs fail replay loudly.
299	 * @param value - candidate durable payload.
300	 * @returns validated run or `undefined` for another value kind.
301	 */
302	export function decodeRunChange(value: unknown): VerificationRunChangeMeta | undefined {
303	  if (!isRecord(value) || value['kind'] !== 'verification/run') return undefined
304	  requireVersion(value)
305	  const treeHash = value['treeHash']
306	  requireKeys(value, treeHash === undefined ? RUN_KEYS : [...RUN_KEYS, 'treeHash'], 'run')
307	  if (typeof value['isolation'] !== 'string' || !ISOLATIONS.has(value['isolation'] as CertificateIsolation)) {
308	    throw new Error('verification change run.isolation is invalid')
309	  }
310	  if (typeof value['executor'] !== 'string' || !EXECUTORS.has(value['executor'] as RunExecutor)) {
311	    throw new Error('verification change run.executor is invalid')
312	  }
313	  if (!Array.isArray(value['results']) || value['results'].length === 0) {
314	    throw new Error('verification change run.results must be a non-empty array')
315	  }
316	  return {
317	    kind: 'verification/run',
318	    version: VERIFICATION_CHANGE_VERSION,
319	    standard: decodeRef(value['standard'], 'run.standard'),
320	    attempt: positiveInteger(value['attempt'], 'run.attempt'),
321	    isolation: value['isolation'] as CertificateIsolation,
322	    executor: value['executor'] as RunExecutor,
323	    results: value['results'].map((result, index) => decodeRunResult(result, `run.results[${index}]`)),
324	    ...treeHash === undefined ? {} : { treeHash: hexDigest(treeHash, 'run.treeHash') },
325	    recordedAt: nonNegativeInteger(value['recordedAt'], 'run.recordedAt'),
326	  }
327	}
328	
329	/**
330	 * Decode a value that declares itself as a certificate. Unrelated values
331	 * return `undefined`; malformed certificates fail replay loudly.
332	 * @param value - candidate durable payload.
333	 * @returns validated certificate or `undefined` for another value kind.
334	 */
335	export function decodeCertificateChange(value: unknown): CertificateChangeMeta | undefined {
336	  if (!isRecord(value) || value['kind'] !== 'verification/certificate') return undefined
337	  requireVersion(value)
338	  requireKeys(value, ['certificate', 'kind', 'version'], 'certificate')
339	  const certificate = value['certificate']
340	  if (!isRecord(certificate)) throw new Error('verification change certificate must be a record')
341	  requireKeys(certificate, ['executor', 'goalId', 'isolation', 'recordedAt', 'results', 'standard'], 'certificate')
342	  if (typeof certificate['goalId'] !== 'string' || certificate['goalId'].length === 0) {
343	    throw new Error('verification change certificate.goalId must be a non-empty string')
344	  }
345	  if (typeof certificate['isolation'] !== 'string'
346	    || !ISOLATIONS.has(certificate['isolation'] as CertificateIsolation)) {
347	    throw new Error('verification change certificate.isolation is invalid')
348	  }
349	  if (typeof certificate['executor'] !== 'string' || !EXECUTORS.has(certificate['executor'] as RunExecutor)) {
350	    throw new Error('verification change certificate.executor is invalid')
351	  }
352	  if (!Array.isArray(certificate['results']) || certificate['results'].length === 0) {
353	    throw new Error('verification change certificate.results must be a non-empty array')
354	  }
355	  return {
356	    kind: 'verification/certificate',
357	    version: VERIFICATION_CHANGE_VERSION,
358	    certificate: {
359	      standard: decodeRef(certificate['standard'], 'certificate.standard'),
360	      goalId: GoalId(certificate['goalId']),
361	      isolation: certificate['isolation'] as CertificateIsolation,
362	      executor: certificate['executor'] as RunExecutor,
363	      results: certificate['results'].map((result, index) =>
364	        decodeCertificateResult(result, `certificate.results[${index}]`)),
365	      recordedAt: nonNegativeInteger(certificate['recordedAt'], 'certificate.recordedAt'),
366	    },
367	  }
368	}
369	
370	/**
371	 * Decode a value that declares itself as a directive. Unrelated values
372	 * return `undefined`; malformed directives fail replay loudly.
373	 * @param value - candidate durable payload.
374	 * @returns validated directive or `undefined` for another value kind.
375	 */
376	export function decodeDirectiveChange(value: unknown): DirectiveChangeMeta | undefined {
377	  if (!isRecord(value) || value['kind'] !== 'verification/directive') return undefined
378	  requireVersion(value)
379	  requireKeys(value, ['detail', 'issuedAt', 'kind', 'rootCause', 'standard', 'version'], 'directive')
380	  return {
381	    kind: 'verification/directive',
382	    version: VERIFICATION_CHANGE_VERSION,
383	    standard: decodeRef(value['standard'], 'directive.standard'),
384	    rootCause: normalizedText(value['rootCause'], 'directive.rootCause'),
385	    detail: normalizedText(value['detail'], 'directive.detail'),
386	    issuedAt: nonNegativeInteger(value['issuedAt'], 'issuedAt'),
387	  }
388	}
389	
390	/** Require two checks to be identical field-for-field. */
391	function requireSameCheck(previous: StandardCheck, next: StandardCheck, subject: string): void {
392	  if (previous.id !== next.id || previous.outcome !== next.outcome || previous.run !== next.run) {
393	    throw new Error(`verification change ${subject} must preserve the existing check "${previous.id}"`)
394	  }
395	}
396	
397	/** Require the relaxed list to preserve an existing prefix exactly. */
398	function requireSameRelaxed(previous: readonly RelaxedCheck[], next: readonly RelaxedCheck[], subject: string): void {
399	  for (const [index, entry] of previous.entries()) {
400	    const candidate = next[index]
401	    if (candidate === undefined || candidate.evidence !== entry.evidence) {
402	      throw new Error(`verification change ${subject} must preserve the existing relaxation of "${entry.check.id}"`)
403	    }
404	    requireSameCheck(entry.check, candidate.check, subject)
405	  }
406	}
407	
408	/** Require one exact next revision of the current standard for the same goal. */
409	function requireNextRevision(
410	  current: CompletionStandardSnapshot,
411	  next: CompletionStandardSnapshot,
412	  operation: string,
413	): void {
414	  if (next.id !== current.id || next.revision !== current.revision + 1 || next.goalId !== current.goalId) {
415	    throw new Error(`verification ${operation} must advance the current standard by one revision for its goal`)
416	  }
417	}
418	
419	/** Require preserved creation time and monotone update time. */
420	function requireTimestampContinuity(
421	  state: VerificationFoldState,
422	  createdAt: number,
423	  updatedAt: number,
424	  operation: string,
425	): void {
426	  /* v8 ignore next -- a current standard established by this fold always has an updatedAt */
427	  if (state.updatedAt === undefined) throw new Error('current standard fold lacks updatedAt')
428	  if (createdAt !== state.createdAt || updatedAt < state.updatedAt) {
429	    throw new Error(`verification ${operation} does not preserve the current timestamps`)
430	  }
431	}
432	
433	/** Validate and apply one standard change (author or extend). */
434	function applyStandardChange(state: VerificationFoldState, change: StandardChangeMeta): void {
435	  const next = change.standard
436	  if (change.operation === 'author') {
437	    if (next.revision !== 1 || next.relaxed.length !== 0 || next.checks.length === 0
438	      || state.seenStandardIds.has(next.id)
439	      || (state.standard !== undefined && state.standard.goalId === next.goalId)) {
440	      throw new Error('verification author requires a fresh revision-one standard for a new goal')
441	    }
442	    state.seenStandardIds.add(next.id)
443	  } else {
444	    const current = state.standard
445	    if (current === undefined) throw new Error('verification extend requires a current standard')
446	    requireNextRevision(current, next, change.operation)
447	    requireTimestampContinuity(state, change.createdAt, change.updatedAt, change.operation)
448	    if (next.checks.length <= current.checks.length) {
449	      throw new Error('verification extend must add at least one check')
450	    }
451	    for (const [index, check] of current.checks.entries()) {
452	      requireSameCheck(check, next.checks[index] as StandardCheck, change.operation)
453	    }
454	    if (next.relaxed.length !== current.relaxed.length) {
455	      throw new Error('verification extend cannot change relaxations')
456	    }
457	    requireSameRelaxed(current.relaxed, next.relaxed, change.operation)
458	  }
459	  state.standard = next
460	  state.certificate = undefined
461	  state.createdAt = change.createdAt
462	  state.updatedAt = change.updatedAt
463	  state.lastRef = { id: next.id, revision: next.revision }
464	}
465	
466	/** Validate and apply one relaxation. */
467	function applyRelaxationChange(state: VerificationFoldState, change: RelaxationChangeMeta): void {
468	  const current = state.standard
469	  if (current === undefined) throw new Error('verification relaxation requires a current standard')
470	  const next = change.standard
471	  requireNextRevision(current, next, 'relaxation')
472	  requireTimestampContinuity(state, change.createdAt, change.updatedAt, 'relaxation')
473	  const removed = current.checks.find(check => check.id === change.checkId)
474	  if (removed === undefined) {
475	    throw new Error(`verification relaxation names unknown check "${change.checkId}"`)
476	  }
477	  const remaining = current.checks.filter(check => check.id !== change.checkId)
478	  if (next.checks.length !== remaining.length) {
479	    throw new Error('verification relaxation must remove exactly its named check')
480	  }
481	  for (const [index, check] of remaining.entries()) {
482	    requireSameCheck(check, next.checks[index] as StandardCheck, 'relaxation')
483	  }
484	  if (next.relaxed.length !== current.relaxed.length + 1) {
485	    throw new Error('verification relaxation must append exactly one relaxed entry')
486	  }
487	  requireSameRelaxed(current.relaxed, next.relaxed, 'relaxation')
488	  const appended = next.relaxed[next.relaxed.length - 1] as RelaxedCheck
489	  requireSameCheck(removed, appended.check, 'relaxation')
490	  state.standard = next
491	  state.certificate = undefined
492	  state.createdAt = change.createdAt
493	  state.updatedAt = change.updatedAt
494	  state.lastRef = { id: next.id, revision: next.revision }
495	}
496	
497	/** Require one result per active check, in the standard's check order. */
498	function requireResultsCover(
499	  current: CompletionStandardSnapshot,
500	  results: readonly CheckResult[],
501	  subject: string,
502	): void {
503	  if (results.length !== current.checks.length) {
504	    throw new Error(`verification ${subject} must carry one result per active check`)
505	  }
506	  for (const [index, check] of current.checks.entries()) {
507	    if (results[index]?.checkId !== check.id) {
508	      throw new Error(`verification ${subject} result ${index} must answer check "${check.id}"`)
509	    }
510	  }
511	}
512	
513	/** Validate and apply one executed run. */
514	function applyRunChange(state: VerificationFoldState, change: VerificationRunChangeMeta): void {
515	  const current = state.standard
516	  if (current === undefined) throw new Error('verification run requires a current standard')
517	  if (change.standard.id !== current.id || change.standard.revision !== current.revision) {
518	    throw new Error('verification run must cover the exact current standard revision')
519	  }
520	  requireResultsCover(current, change.results, 'run')
521	  /* v8 ignore next -- a current standard established by this fold always has an updatedAt */
522	  if (state.updatedAt === undefined) throw new Error('current standard fold lacks updatedAt')
523	  if (change.recordedAt < state.updatedAt) {
524	    throw new Error('verification run cannot precede the current standard update')
525	  }
526	  const expected = nextRunAttempt(state, current.id)
527	  if (change.attempt !== expected) {
528	    throw new Error(`verification run must number attempt ${expected} for standard "${current.id}"`)
529	  }
530	  state.runsRecorded += 1
531	  state.lastRun = change
532	}
533	
534	/** Validate and apply one certificate. */
535	function applyCertificateChange(state: VerificationFoldState, change: CertificateChangeMeta): void {
536	  const current = state.standard
537	  if (current === undefined) throw new Error('verification certificate requires a current standard')
538	  const certificate = change.certificate
539	  if (certificate.standard.id !== current.id || certificate.standard.revision !== current.revision
540	    || certificate.goalId !== current.goalId) {
